; source: textio.p8:34

    ALIGN 2

p8b_txt.p8s_nl:
        ; load.b r135.b,#10.b
        ; call p8b_txt.p8s_chrout(r135.b@s10)
    moveq  #10,d0
    bsr  p8b_txt.p8s_chrout
        ; return
    rts
; End of subroutine: p8b_txt.p8s_nl

