; Block: sys

sys:
; ---- Subroutine: sys.reset_system ----

    ALIGN 2

sys.reset_system:
            move.l  4.w,a6
            move.w  20(a6),d0       ; ExecBase version
            cmpi.w  #36,d0
            bge.s   .cold_reboot

            move.l  4.w,a0          ; Kickstart 1.3 fallback
            reset
            move.l  (a0),a0
            jmp     (a0)

.cold_reboot:
            jmp     -726(a6)       ; ColdReboot()
; End of subroutine: sys.reset_system


; ---- Subroutine: sys.wait ----
    ALIGN 2

sys.wait:
            move.l  sys.DOSBase,a6
            jmp     -198(a6)        ; Delay
; End of subroutine: sys.wait


; ---- Subroutine: sys.exit ----
    ALIGN 2

sys.exit:
            and.l    #$ffff,d0
            move.l   p8_sys_startup.orig_stackpointer,sp
            jmp  p8_sys_startup.cleanup_at_exit
; End of subroutine: sys.exit

; ---- Subroutine: sys.set_carry ----
; source: syslib.p8:96

    ALIGN 2

sys.set_carry:
            ; set both C (comparison carry) and X (rotate carry) bits
            moveq  #$11,d0
            move.w  d0,ccr
        ; return
    rts
; End of subroutine: sys.set_carry

; ---- Subroutine: sys.clear_carry ----
; source: syslib.p8:105

    ALIGN 2

sys.clear_carry:
            ; clear C and X bits
            moveq  #0,d0
            move.w  d0,ccr
        ; return
    rts
