p8b_prog8_defer:
; ---- Subroutine: p8b_prog8_defer.p8s_defer_unwind_all ----

    ALIGN 2

p8b_prog8_defer.p8s_defer_unwind_all:
; stack frame: 2 bytes of locals, 0 bytes of arguments
    link  a5,#-2
    clr.w  -2(a5)
        ; loadm.b r540.b,[p8b_prog8_defer.p8v_defer_guard]
    move.b  p8b_prog8_defer.p8v_defer_guard,p8_regfile+1674
        ; cmpi.b r540.b,#0.b
    tst.b  p8_regfile+1674
        ; bsteq p8_label_gen_118
    beq  p8_label_gen_118
        ; return
    unlk  a5
    rts

p8_label_gen_118:
        ; storeim.b #1.b,[p8b_prog8_defer.p8v_defer_guard]
    move.b  #1,p8b_prog8_defer.p8v_defer_guard

p8b_prog8_defer.p8s_defer_unwind_all.p8l_defer_unwind_loop:
        ; loadm.w r541.w,[p8b_prog8_defer.p8v_defer_sp]
    move.w  p8b_prog8_defer.p8v_defer_sp,p8_regfile+1676
        ; cmpi.w r541.w,#0.w
    tst.w  p8_regfile+1676
        ; bsteq p8b_prog8_defer.p8s_defer_unwind_all.p8l_defer_unwind_done
    beq  p8b_prog8_defer.p8s_defer_unwind_all.p8l_defer_unwind_done
        ; decm.w [p8b_prog8_defer.p8v_defer_sp]
    subq.w  #1,p8b_prog8_defer.p8v_defer_sp
        ; loadm.w r542.w,[p8b_prog8_defer.p8v_defer_sp]
    move.w  p8b_prog8_defer.p8v_defer_sp,p8_regfile+1678
        ; loadx.b r543.b,[p8b_prog8_defer.p8v_defer_handler_stack+r542.w]
    move.w  p8_regfile+1678,d0
    lea  p8b_prog8_defer.p8v_defer_handler_stack,a0
    move.b  (a0,d0.w),d0
    move.b  d0,p8_regfile+1680
        ; ext.b r544.w,r543.b
    moveq  #0,d0
    move.b  p8_regfile+1680,d0
    move.w  d0,p8_regfile+1682
        ; storem.w r544.w,[frame:-2]
    move.w  p8_regfile+1682,-2(a5)
        ; loadm.w r545.w,[frame:-2]
    move.w  -2(a5),p8_regfile+1684
        ; cmpi.w r545.w,#1.w
    cmpi.w  #1,p8_regfile+1684
        ; bsteq p8_label_gen_120
    beq  p8_label_gen_120
        ; cmpi.w r545.w,#2.w
    cmpi.w  #2,p8_regfile+1684
        ; bsteq p8_label_gen_121
    beq  p8_label_gen_121
        ; jump p8_label_gen_119
    bra  p8_label_gen_119

p8_label_gen_120:
        ; call dos.read_file.prog8_invoke_defers()
    bsr  dos.read_file.prog8_invoke_defers
        ; jump p8_label_gen_119
    bra  p8_label_gen_119

p8_label_gen_121:
        ; call p8b_main.p8s_start.p8s_prog8_invoke_defers()
    bsr  p8b_main.p8s_start.p8s_prog8_invoke_defers
        ; jump p8_label_gen_119
    bra  p8_label_gen_119

p8_label_gen_119:
        ; jump p8b_prog8_defer.p8s_defer_unwind_all.p8l_defer_unwind_loop
    bra  p8b_prog8_defer.p8s_defer_unwind_all.p8l_defer_unwind_loop

p8b_prog8_defer.p8s_defer_unwind_all.p8l_defer_unwind_done:
    clr.b  p8b_prog8_defer.p8v_defer_guard
        ; return
    unlk  a5
    rts
